def solve(inputs: dict) -> float:
    M = inputs["M"]
    n = inputs["n"]
    mod = inputs["mod"]

    # Convert M to list if needed
    if isinstance(M, list):
        matrix = [row[:] for row in M]
    else:
        matrix = M

    # Matrix multiplication with modulo
    def matrix_mult(A, B, mod):
        size = len(A)
        result = [[0] * size for _ in range(size)]
        for i in range(size):
            for j in range(size):
                for k in range(size):
                    result[i][j] = (result[i][j] + A[i][k] * B[k][j]) % mod
        return result

    # Matrix exponentiation using binary exponentiation
    def matrix_power(M, n, mod):
        size = len(M)
        # Initialize result as identity matrix
        result = [[1 if i == j else 0 for j in range(size)] for i in range(size)]
        base = [row[:] for row in M]

        while n > 0:
            if n % 2 == 1:
                result = matrix_mult(result, base, mod)
            base = matrix_mult(base, base, mod)
            n //= 2

        return result

    result_matrix = matrix_power(matrix, n, mod)

    # Sum all entries
    total = sum(sum(row) for row in result_matrix)
    return float(total)

